const { parentPort, workerData } = require('node:worker_threads');
const vm = require('node:vm');

function serializeError(error) {
  let name = 'Error';
  let message = 'Experiment policy execution failed';
  let code;
  try {
    if (error && typeof error === 'object') {
      if (typeof error.name === 'string') name = error.name.slice(0, 128);
      if (typeof error.message === 'string') message = error.message.slice(0, 512);
      if (typeof error.code === 'string') code = error.code.slice(0, 128);
    }
  } catch {}
  return { name, message, code };
}

